  'Write, sketch, or build something': { ar: 'اكتب، ارسم، أو ابنِ شيئاً', pt: 'Escreva, desenhe ou construa algo', es: 'Escribe, dibuja o construye algo', de: 'Schreibe, zeichne oder baue etwas', fr: 'Écris, dessine ou construis quelque chose', it: 'Scrivi, disegna o costruisci qualcosa' },
  'Organize one drawer / folder': { ar: 'نظّم درجاً أو مجلداً واحداً', pt: 'Organize uma gaveta / pasta', es: 'Organiza un cajón / carpeta', de: 'Ordne eine Schublade / einen Ordner', fr: 'Range un tiroir / un dossier', it: 'Organizza un cassetto / una cartella' },
